SELECT MAX (生日) AS 年龄
FROM 职工
Where [性别]="男";

SELECT MAX (YEAR (生日)) AS 年龄
FROM 职工
Where [性别]="男";

SELECT MAX (DATEDIFF ("YYYY",YEAR (生日),YEAR (DATE ())) AS 年龄
FROM 职工
Where [性别]="男";

SELECT MAX (DATEDIFF ("YYYY", 生日，DATE ()) AS 年龄
FROM 职工
Where [性别]="男";

SELECT Min (Year (Date ())-Year ([生日])) AS 年龄
FROM 职工
WHERE [性别]="男";

SELECT 年龄
FROM 职工
WHERE Min (Year (Date ())-Year ([生日])) AND [性别]="男";

